// ---------------------------------------------------------------
// Process: SC_METHOD wait_for_end
// Static sensitivity: sensitive << clk.pos() << testbench_end_event;

void mc_testbench::wait_for_end() {
   // If run() has not finished, we do nothing here
   if (!testbench_ended) return;
   // check for completed outputs
   if (fir_output_comp->get_compare_count() < fir_output_capture_count) {testbench_end_event.notify(1,SC_NS); return;}
   if (iir_output_comp->get_compare_count() < iir_output_capture_count) {testbench_end_event.notify(1,SC_NS); return;}
   // If we made it here, all outputs have flushed. Check the results
   testbench_aw_event.notify(SC_ZERO_TIME);
   SC_REPORT_INFO(name(), "Simulation completed");
   check_results();
   sc_stop();
}
// ---------------------------------------------------------------
// Process: SC_THREAD run
// Static sensitivity: 

void mc_testbench::run() {
   testbench::enable_idle_sync_mode = false;
   testbench::idle_sync_stable_cycles = 1;
   _channel_mismatch = false;
   testbench::input_ignore = false;
   testbench::input_skip = false;
   testbench::input_skip_quiet = false;
   testbench::input_skip_once = false;
   testbench::input_skip_noerr = false;
   testbench::input_array_comp_first = -1;
   testbench::input_array_comp_last = -1;
   testbench::input_wait_ctrl.clear();
   input_capture_count = 0;
   input_iteration_count = 0;
   testbench::fir_output_ignore = false;
   testbench::fir_output_skip = false;
   testbench::fir_output_skip_quiet = false;
   testbench::fir_output_skip_once = false;
   testbench::fir_output_skip_noerr = false;
   testbench::fir_output_array_comp_first = -1;
   testbench::fir_output_array_comp_last = -1;
   testbench::fir_output_use_mask = false;
   testbench::fir_output_output_mask = (int) ~0;
   testbench::fir_output_wait_ctrl.clear();
   fir_output_capture_count = 0;
   fir_output_iteration_count = 0;
   testbench::iir_output_ignore = false;
   testbench::iir_output_skip = false;
   testbench::iir_output_skip_quiet = false;
   testbench::iir_output_skip_once = false;
   testbench::iir_output_skip_noerr = false;
   testbench::iir_output_array_comp_first = -1;
   testbench::iir_output_array_comp_last = -1;
   testbench::iir_output_use_mask = false;
   testbench::iir_output_output_mask = (int) ~0;
   testbench::iir_output_wait_ctrl.clear();
   iir_output_capture_count = 0;
   iir_output_iteration_count = 0;
   testbench testbench_inst(sc_argc(), sc_argv());
   main_exit_code = testbench_inst.main();
   cout<<"Info: Execution of user-supplied C++ testbench 'main()' has completed with exit code = " << main_exit_code << endl;
   cout<<endl;
   cout<<"Info: Collecting data completed"<<endl;
   cout<<"   captured "<<input_capture_count<<" values of input"<<endl;
   cout<<"   captured "<<fir_output_capture_count<<" values of fir_output"<<endl;
   cout<<"   captured "<<iir_output_capture_count<<" values of iir_output"<<endl;
   testbench_ended = true;
   testbench_end_event.notify(SC_ZERO_TIME);
}
